        name = "'" + name
    writer.writerow([row["MaSP"], name,
                     row["SoLuong"], str(row["DoanhThu"])])

@contextmanager
def transaction():
    connection = connect()
    try:
        connection.execute("SET XACT_ABORT ON")
        yield connection.cursor()
        connection.commit()
    except Exception:
        connection.rollback()
        raise
    finally:
        connection.close()
